import React , {useEffect, useState} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId, updStore, hasWritePrivilege, ObjectKeys, getLabelTranslate, blobfromArray, parseDateMMDDYY } from "../../../stores/Utils";

import { useNavigate } from "react-router";
import { CloseModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt } from "../../../components";
import { get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import { getall_product } from "../../Inventory/services/server_fetching";
import { getall_provider } from "../../ProvidersCustomers/services/server_fetching";



const Svg = SvgIcon_Cmpt();



const ViewInvoice  = ({ data, item }) => {

	const [obs, set_obs] = useState(0);


	
	useEffect(() => {
		updStore("inv_products_list", null);
		updStore("inv_products_stock",null);

		if(!(getStore("providers_ids")?.[ item?.customer?.providerId]?.name)){
			getall_provider(updObs);
		}

		if(!getStore("products_ids")){
			//Log$$("fetching products")
			getall_product(updObs);
		}
		
		
		get_balances_by_type("global_accounts","global_account_params",updObs);
		updObs();
		//get_inventory_by_prod(item.productId,updObs)
	},[item.productId]);

	const updObs =  () => {
		set_obs(gen16CodeId())
	}




	const navigate = useNavigate();

	const close =  (element) => {
		CloseModal({id:data.modalID});
		
	}
	


	let TotalAmount =  item?.hasTax? item?.hasTax + item?.amount : item?.amount*1;

	const printInvoice =  () => {
		let data2print =  {...item};
		// Invoice2Pdf(data2print)

		
	}

	const printInvoiceLbl =  () => {
		let data2print =  {...item};
		//  InvoiceLabelsPdf1X3([data2print])
		
	}


	


	let hasAdvancePay = item?. hasAdvancePay? item?.hasAdvancePay  : 0;

	return (
		<div style={{
			maxHeight: "94vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 30px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect gSansFont">
					{ "Invoice:" } 
				</p>
				<p className="title_collect fntW600 gSansFont" style={{color: "#646cff"}}>
					{ item?.document} 
				</p>
				<div className="flexSpace"/>
				{hasWritePrivilege()?
				<div className="code comprobante_id  gSansFont" style={{color: "#646cff", paddingTop: 10}}>
					{item?.comprobanteId} 
				</div>:null}
				<div className="icon_print" onClick={printInvoiceLbl}>
					<Svg name={"printer"} color={"var(--hrm_palette-static-ad-yellow)"}/>
				</div>
				<div className="icon_print" onClick={printInvoice}>
					<Svg name={"printer"} color={"var(--hrm_palette-inverse-background-b)"}/>
				</div>
			</div>

			<div className="acc_dtls" style={{marginTop: 10, marginLeft: 2}}>
			
				<div className="_dsplFlx"  >
					<div className="name">
						<div className=" code gSansFont" style={{ color: "var(--hrm_palette-inverse-background-b)"}} >
							{parseDateMMDDYYYY(item?.date)} 
						</div>
					</div>
					<div className="flexSpace"/>
					<div className="_dsplFlx"  >
						<div className="name gSansFont" style={{ marginRight: 5, color: "var(--hrm_palette-item_coll_gray)"}}>
							Bill To: 
						</div>
						<div className="code gSansFont" style={{color: "#646cff"}}>
							{ getStore("providers_ids")?.[ item?.customer?.providerId]?.name } 
						</div>
					</div>
					
				</div>
			</div>
			
			
			<div className="_dsplFlx " style={{marginBottom: 8}}>
				
				<div className="flexSpace"/>
				<div className="_dsplFlx"  >
					<div className="name gSansFont" style={{color: "var(--hrm_palette-item_coll_gray)"}}>
					{item?.description} 
					</div>
				</div>
			
			</div>

					


			
			<div className="_dsplFlx hdr_bar purple">
				<div className="tr_bar_70"  style={{textAlign:"left", paddingLeft: 14}}>
					{getLabelTranslate(4)}
				</div>
				<div className="tr_bar_15 txt_alg_padd" >
					{getLabelTranslate(10)}
				</div>
				<div className="tr_bar_15 txt_alg_padd">
					{getLabelTranslate(14)}
				</div>
			</div>
			
			<div className="scollVh subMHeight" style={{height: "calc(84vh - 142px)"}}>
			{item.products && item.products?.map((element) => 
				<ListingProducts 
					key={element.inventoryId} 
					element={element} 
					idKey={element.inventoryId} 
					close={close}
				/>
			)}
			{item.extras && ObjectKeys(item.extras)?.map((element) => 
				<ListingExtras 
					key={element} 
					element={item.extras[element]} 
					idKey={element} 
					close={close}
				/>)}
				<div className="_dsplFlx totalsGrid" style={{margin:"19px 15px 10px"}} >
					<div className="tr_bar_70"/>
					<div className="tr_bar_30 brdTp">
						<div className="_dsplFlx totals"  >
							<div className="code tr_bar_70 gSansFont"  >
								{"Subtotal:"} 
							</div>
							<div className="name tr_bar_30 gSansFont" >
								${item?. amount?.toFixed(2)} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_60 gSansFont" >
								{"tax:"} 
							</div>
							<div className="name tr_bar_40 gSansFont" >
								${item?.hasTax ? item?.hasTax.toFixed(2):"0.00"} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_60 fntW600 gSansFont"  style={{color: "var(--hrm_palette-inverse-background-b)"}}>
								{"Total:"} 
							</div>
							<div className="name tr_bar_40  gSansFont fntW600"  style={{color: "var(--hrm_palette-inverse-background-b)"}}>
								${TotalAmount?.toFixed(2)} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_60 gSansFont" >
								{"Advance Payment:"} 
							</div>
							<div className="name tr_bar_40  gSansFont" >
								${hasAdvancePay?.toFixed(2)} 
							</div>	
						</div>
						<div className="_dsplFlx totals" >
							<div className="code tr_bar_60 fntW600 gSansFont"   style={{color: "#646cff" }}>
								{"Balance Due:"} 
							</div>
							<div className="name tr_bar_40 fntW600 gSansFont"  style={{color: "#646cff"}}>
								${(TotalAmount - hasAdvancePay)?.toFixed(2)} 
							</div>	
						</div>

					</div>
				</div>
			</div>
			
		</div>
	);
};

export default ViewInvoice;









const ListingProducts  = ({ element, idKey, close }) => {
	let product = getStore("products_ids")?.[element?.product];

	let amount = element.qty*1 ?element.qty*1*element.salePrice:0;
	return (
		<div className="_dsplFlx hdr_bar">
			<div className="tr_bar_70 gSansFont" style={{textAlign:"left", paddingLeft: 14}}>
				{product?.name}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element.qty)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{amount?.toFixed(2)}
			</div>
			
		</div>
	)

}


const ListingExtras  = ({ element, idKey, close }) => {


	return (
		<div className="_dsplFlx hdr_bar">
			<div className="tr_bar_70  gSansFont" style={{textAlign:"left", paddingLeft: 14}}>
				{element?.description}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont" >
				{(element.qty*1)?.toFixed(2)}
			</div>
			<div className="tr_bar_15 numbAlign gSansFont">
				{(element.qty*1)?((element.qty*1)*element.salePrice*1)?.toFixed(2):""}
			</div>
			
		</div>
	)

}


